local __ID = 0

---@class ExhibitBuilder
ExhibitBuilder = class("ExhibitBuilder")

function ExhibitBuilder:initialize()
    __ID = __ID + 1
    self.ID = __ID
    self.serverID=-1
    self.exhibitID =-1
    self.exhibitConfigName =""
    self.LoadProgress = 1
    self.finishEvt = nil
    self.finishParam = nil
    self.isLoading = false
    self.Root = nil
    self.RootParent=nil
    self.slotBoxRootDic={}
    self.cs_Start = nil
    self.timerId = -1
end
function ExhibitBuilder:SetExhibitID(exhibitID)
    self.exhibitID = exhibitID
    ---@type dictexhibit_config_cell
    local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config, exhibitID)
    if cfgdata~=nil then
        self.exhibitConfigName =cfgdata.configName
    end
end

function ExhibitBuilder:GetBuilderID()
    return self.ID
end

function ExhibitBuilder:GetExhibitID()
    return self.exhibitID
end

function ExhibitBuilder:GetExhibitResName()
    return self.exhibitConfigName
end

function ExhibitBuilder:GetRoot()
    return  self.Root
end

function ExhibitBuilder:GetSlotBoxRootBySlot(slot)
    return self.slotBoxRootDic[slot]
end

function ExhibitBuilder:SetRootParent(parent,isreset)
    if isreset == nil then
        isreset =false
    end
    UIUtil.SetParentTransform(parent,self.Root,isreset)

end

function ExhibitBuilder:SetObj(obj)
    self.Root=obj
    self:SlotInit()
    CommonHelper:CSGameObjectSetActive(self.Root ,false)
    mono.SetLayerName(self.Root,"Default")
end

function ExhibitBuilder:SlotInit()
    ---@type  ExhibitData @展品
    local exhibitData = PersonalHomeDataManager:Get():GetExhibitByServerID(self.serverID)
    for slotID, pointName in pairs(exhibitData:GetSlotNameDic()) do
        local slotRoot = UIUtil.GetChild(pointName,self.Root)
        if slotRoot then
            if  self.slotBoxRootDic[slotID] == nil then
                self.slotBoxRootDic[slotID] = ExhibitBoxMgr:Get():GetBox(slotRoot,exhibitData:GetServerID(),slotID,exhibitData:GetSlotTypeDic()[slotID],exhibitData:GetSlotBoxSizeDic()[slotID])
            end
        else
            logError(self:GetExhibitResName(),"没有该节点:",pointName)
        end
    end
end

--------------------------------------回收
function ExhibitBuilder:Recycle(isDestroy)
    self:BreakBuild()
    if isDestroy then
        self:RecycleDestroyObj()
    else
        self:RecycleObj()
    end
    self:ClearCache()
end

function ExhibitBuilder:RecycleObj()
    ExhibitCacheMgr:Get():RecycleExhibit(self:GetRoot(),false)
end

function ExhibitBuilder:RecycleDestroyObj()
    ExhibitCacheMgr:Get():RecycleExhibit(self:GetRoot(),true)
end


function ExhibitBuilder:ClearCache()
    self.LoadProgress = 1
    self.finishEvt = nil
    self.finishParam = nil
    self.isLoading = false
    self.Root = nil
    self.RootParent=nil
    self.slotBoxRootDic={}
    self.cs_Start = nil

    self:StopTimer()
end

function ExhibitBuilder:BuilderExhibit(isrebuild)
    if self.isLoading then
        log("---   BuilderExhibit Error")
        return
    end

    --CarBuilderManager:Get():AddBuildMask()

    self.isLoading = true
    self.LoadProgress = 0


    self:StartTimer()

    self:LoadAsset()

    self:CoroutineStart(isrebuild)
end



function ExhibitBuilder:CoroutineStart(isrebuild)
    ---@param exhibitBuilder ExhibitBuilder
    self.cs_Start = cs_coroutine.start(function(exhibitBuilder)
        log("    exhibitBuilder id  ",exhibitBuilder:GetExhibitID())
        ---@type dictexhibit_config_cell
        while ExhibitCacheMgr:Get():IsLoadFinish(exhibitBuilder:GetExhibitResName())==false do
            coroutine.yield()
        end
        coroutine.yield()
        exhibitBuilder:StartBuild(isrebuild)
    end,self)
end

function ExhibitBuilder:LoadAsset()
    ExhibitCacheMgr:Get():LoadExhibit(self:GetExhibitResName())
end

function ExhibitBuilder:StartBuild(isrebuild)

    self:BuildEntity()

    self.LoadProgress = 0.7

    self:OnBuildFinish(isrebuild)
end

function ExhibitBuilder:BuildEntity()
    self:SetObj(ExhibitCacheMgr:Get():SwapExhibit(self:GetExhibitResName()))
    self:SetRootParent(ExhibitCacheMgr:Get().Root)
end

function ExhibitBuilder:GetProgress()
    return self.LoadProgress
end

function ExhibitBuilder:StartTimer()
    self:StopTimer()
    ---@param class ExhibitBuilder
    self.timerId = TimerManager:Get():CreateTimer(10, function(class)
        class:BuildOvertime()
    end, self)
end
function ExhibitBuilder:StopTimer()
    TimerManager:Get():StopTimer(self.timerId)
    self.timerId = -1
end

function ExhibitBuilder:BuildOvertime()
    self:StopTimer()
    log("---   error:carbuilder overtime...   type,id = ",self.BuildType, self.newCarID, self.tableID, self.suitID)
    --CarBuilderManager:Get():RemoveBuildMask()
end


function ExhibitBuilder:OnBuildFinish(isrebuild)
    self.cs_Start = nil
    self.isLoading = false
    self:StopTimer()
    self:OnCombineFinish(isrebuild)
    --CarBuilderManager:Get():RemoveBuildMask()
end

function ExhibitBuilder:OnCombineFinish(isrebuild)
    self.LoadProgress = 1

    if self.Parent then
        UIUtil.SetParentGameObject(self.Parent, self.Root,false)
    else
        UIUtil.SetParentGameObject(ExhibitCacheMgr:Get():GetRoot(), self.Root,false)
    end

    if self.finishEvt then
        self.finishEvt(self, self.finishParam)
    end
end


function ExhibitBuilder:BreakBuild()
    if self.cs_Start then
        cs_coroutine.stop(self.cs_Start)
        self.cs_Start = nil
    end
end


